# [doc = ""] # [doc = " This current does not support `f32` nor `f64`, as they're not needed in any"] # [doc = " serialized data structures. That could be changed, but consider whether it"] # [doc = " really makes sense to store floating-point values at all."] # [doc = " (If you need it, revert <https://github.com/rust-lang/rust/pull/109984>.)"] pub trait Decoder { fn read_usize (& mut self) -> usize ; fn read_u128 (& mut self) -> u128 ; fn read_u64 (& mut self) -> u64 ; fn read_u32 (& mut self) -> u32 ; fn read_u16 (& mut self) -> u16 ; fn read_u8 (& mut self) -> u8 ; fn read_isize (& mut self) -> isize ; fn read_i128 (& mut self) -> i128 ; fn read_i64 (& mut self) -> i64 ; fn read_i32 (& mut self) -> i32 ; fn read_i16 (& mut self) -> i16 ; # [inline] fn read_i8 (& mut self) -> i8 { self . read_u8 () as i8 } # [inline] fn read_bool (& mut self) -> bool { let value = self . read_u8 () ; value != 0 } # [inline] fn read_char (& mut self) -> char { let bits = self . read_u32 () ; std :: char :: from_u32 (bits) . unwrap () } # [inline] fn read_str (& mut self) -> & str { let len = self . read_usize () ; let bytes = self . read_raw_bytes (len + 1) ; assert ! (bytes [len] == STR_SENTINEL) ; unsafe { std :: str :: from_utf8_unchecked (& bytes [.. len]) } } # [inline] fn read_byte_str (& mut self) -> & [u8] { let len = self . read_usize () ; let bytes = self . read_raw_bytes (len + 1) ; assert ! (bytes [len] == BYTE_STR_SENTINEL) ; & bytes [.. len] } fn read_raw_bytes (& mut self , len : usize) -> & [u8] ; fn peek_byte (& self) -> u8 ; fn position (& self) -> usize ; }